glsl:
float hzHash(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);}
float hzLine(float d,float w){return 1.0-smoothstep(w,w+uPx*1.4,abs(d));}
mat2 hzRot(float a){float c=cos(a),s=sin(a);return mat2(c,-s,s,c);}
vec3 hzPalette(float t){return mix(vec3(1.0,0.25,0.08),vec3(1.0,0.82,0.54),smoothstep(0.0,1.0,t));}
vec4 hafizePortrait(vec2 p){
  float time=uFlow*0.42;
  float energy=clamp(uEnergy+uSpeak*uVoice*0.3,0.0,1.3);
  vec2 q=p;
  q*=hzRot(0.08*sin(time*0.37));
  float r=length(q);
  float a=atan(q.y,q.x);
  float alpha=0.0;
  vec3 col=vec3(0.0);
  float breath=1.0+0.035*sin(time*1.7)+0.07*energy;
  q/=breath; r=length(q); a=atan(q.y,q.x);
  for(int i=0;i<7;i++){
    float fi=float(i);
    float phase=a*3.0+time*(0.24+fi*0.017)+fi*0.897;
    float petal=0.31+0.075*sin(phase)+0.028*sin(a*9.0-time*0.7+fi);
    float ribbon=hzLine(r-petal,0.006+0.002*energy);
    float gate=0.35+0.65*pow(0.5+0.5*cos(a-fi*0.897-time*0.045),3.0);
    float glow=exp(-abs(r-petal)*(46.0-9.0*energy))*0.17*gate;
    vec3 tint=hzPalette(fract(fi*0.19+r+0.18*sin(time)));
    col+=tint*(ribbon*(0.55+0.45*gate)+glow);
    alpha=max(alpha,ribbon*gate+glow);
  }
  float iris=hzLine(r-(0.17+0.012*sin(time*2.1)),0.005);
  float iris2=hzLine(r-(0.12+0.018*energy),0.0035);
  col+=vec3(1.0,0.48,0.2)*iris*0.8+vec3(1.0,0.88,0.7)*iris2;
  alpha=max(alpha,max(iris*0.9,iris2));
  float voidGlow=exp(-r*15.0)*(0.32+0.55*energy);
  col+=vec3(1.0,0.36,0.12)*voidGlow;
  alpha=max(alpha,voidGlow*0.82);
  for(int j=0;j<24;j++){
    float fj=float(j);
    float seed=hzHash(vec2(fj,4.7));
    float pa=fj*2.39996+time*(0.035+0.09*seed);
    float pr=0.19+0.30*seed+0.025*sin(time*(0.7+seed)+fj);
    vec2 star=vec2(cos(pa),sin(pa))*pr;
    float d=length(q-star);
    float pulse=0.55+0.45*sin(time*2.0+fj*1.71);
    float dotv=(1.0-smoothstep(0.004,0.011+0.004*energy,d))*pulse;
    col+=hzPalette(seed)*dotv*(0.65+0.55*energy);
    alpha=max(alpha,dotv);
  }
  float arcAngle=a+0.16*sin(time*0.6);
  float broken=step(0.42,fract(arcAngle*1.43+time*0.035));
  float orbit=hzLine(r-0.51,0.0028)*broken*(0.4+0.6*energy);
  col+=vec3(1.0,0.65,0.4)*orbit;
  alpha=max(alpha,orbit*0.72);
  float horizon=exp(-abs(q.y+0.015*sin(q.x*9.0-time))*72.0)*smoothstep(0.53,0.1,abs(q.x))*0.15;
  col+=vec3(1.0,0.31,0.1)*horizon;
  alpha=max(alpha,horizon);
  float vignette=1.0-smoothstep(0.50,0.61,r);
  col*=vignette*(0.92+0.08*uLight);
  alpha*=vignette;
  col=1.0-exp(-col*(1.35+0.5*energy));
  return vec4(col,clamp(alpha,0.0,1.0));
}
